"""
Batch adaptive filtering for volatile non-stationary signals.

The output is aligned to the requested window right edge:
output[j] estimates input[j + window_size - 1].
"""
import numpy as np

try:
    from scipy.signal import savgol_filter, butter, sosfiltfilt
    from scipy.interpolate import UnivariateSpline, PchipInterpolator
    _HAVE_SCIPY = True
except Exception:
    _HAVE_SCIPY = False


def _finite_signal(x):
    x = np.asarray(x, dtype=float).reshape(-1).copy()
    if x.size == 0:
        return x
    good = np.isfinite(x)
    if not np.any(good):
        return np.zeros_like(x)
    if not np.all(good):
        ii = np.arange(x.size)
        x[~good] = np.interp(ii[~good], ii[good], x[good])
    return x


def adaptive_filter(x, window_size=20):
    x = _finite_signal(x)
    if len(x) < window_size:
        raise ValueError("Input signal length must be >= window_size")
    return np.convolve(x, np.ones(window_size) / float(window_size), mode="valid")


def _odd_span(value, n):
    largest = n if n % 2 else n - 1
    if largest < 3:
        return largest
    return min(max(3, int(round(value)) | 1), largest)


def _fallback_smooth(x, span):
    if span < 3:
        return x.copy()
    p = span // 2
    return np.convolve(
        np.pad(x, p, mode="edge"),
        np.ones(span, dtype=float) / float(span),
        mode="valid",
    )


def _reversals(z):
    d = np.diff(z)
    if d.size < 2:
        return 0
    eps = 1e-8 * (np.std(z) + 1.0)
    s = np.sign(d)
    for i in range(len(s)):
        if abs(d[i]) <= eps:
            s[i] = s[i - 1] if i else 0.0
    return int(np.sum(s[1:] * s[:-1] < 0))


def _safe_corr(a, b):
    sa, sb = np.std(a), np.std(b)
    if sa < 1e-12 or sb < 1e-12:
        return 0.0
    c = np.corrcoef(a, b)[0, 1]
    return float(c) if np.isfinite(c) else 0.0


def _quality(x, z):
    scale = np.std(x) + 1e-8
    mae = np.mean(np.abs(x - z)) / scale
    return mae + 0.022 * _reversals(z) - 0.10 * max(0.0, _safe_corr(x, z))


def _spline_candidates(x):
    if not _HAVE_SCIPY or len(x) < 5:
        return []
    n = len(x)
    scale = float(np.var(x))
    if not np.isfinite(scale) or scale < 1e-16:
        return [x.copy()]
    t = np.arange(n, dtype=float)
    out = []
    for factor in (0.02, 0.05, 0.12, 0.25, 0.50, 1.0):
        try:
            z = np.asarray(
                UnivariateSpline(t, x, k=3, s=n * scale * factor)(t),
                dtype=float,
            )
            if z.shape == x.shape and np.all(np.isfinite(z)):
                out.append(z)
        except Exception:
            pass
    return out


def _ssa_candidates(x, window_size):
    """Bounded singular-spectrum reconstructions via Hankel diagonal averaging."""
    n = len(x)
    if n < 16:
        return []
    L = min(max(8, 2 * int(window_size)), 48, n // 2)
    if L < 4 or n - L + 1 < 4:
        return []
    try:
        h = np.lib.stride_tricks.sliding_window_view(x, L).T.copy()
        u, s, vt = np.linalg.svd(h, full_matrices=False)
    except Exception:
        return []

    ranks = sorted(set(r for r in (2, 4, 6, 8) if r < min(h.shape)))
    out = []
    rows = np.arange(L)[:, None]
    cols = np.arange(h.shape[1])[None, :]
    indices = (rows + cols).ravel()
    counts = np.bincount(indices, minlength=n).astype(float)

    for r in ranks:
        try:
            recon = (u[:, :r] * s[:r]) @ vt[:r]
            sums = np.bincount(indices, weights=recon.ravel(), minlength=n)
            z = sums / np.maximum(counts, 1.0)
            if np.all(np.isfinite(z)):
                out.append(z)
        except Exception:
            pass
    return out


def _persistent_extrema_candidate(trends, n, radius):
    if not _HAVE_SCIPY or len(trends) < 2 or n < 5:
        return None

    extrema = []
    for z in trends:
        d = np.diff(z)
        s = np.sign(d)
        for i in range(1, len(s)):
            if s[i] == 0:
                s[i] = s[i - 1]
        points = []
        for i in range(1, len(s)):
            if s[i - 1] * s[i] < 0:
                points.append((i, 1 if s[i - 1] > 0 else -1))
        extrema.append(points)

    keep = []
    for idx, typ in extrema[0]:
        persistent = False
        for other in extrema[1:]:
            if any(ot == typ and abs(oi - idx) <= radius for oi, ot in other):
                persistent = True
                break
        if persistent:
            keep.append(idx)

    knots = np.array(sorted(set([0, n - 1] + keep)), dtype=int)
    if len(knots) < 2:
        return None
    values = np.median(np.vstack([z[knots] for z in trends]), axis=0)
    try:
        z = np.asarray(PchipInterpolator(knots, values)(np.arange(n)), dtype=float)
        return z if np.all(np.isfinite(z)) else None
    except Exception:
        return None


def enhanced_filter_with_trend_preservation(x, window_size=20):
    x = _finite_signal(x)
    n = len(x)
    if n < window_size:
        raise ValueError("Input signal length must be >= window_size")
    if n <= 3:
        return x[window_size - 1:].copy()

    candidates = [x.copy()]
    trend_scales = []
    spans = []
    for mult in (0.75, 1.0, 1.5, 2.0, 3.0):
        sp = _odd_span(mult * window_size, n)
        if sp >= 3 and sp not in spans:
            spans.append(sp)

    for sp in spans:
        if _HAVE_SCIPY:
            try:
                order = 2 if sp < 7 else 3
                z = savgol_filter(x, sp, order, mode="interp")
            except Exception:
                z = _fallback_smooth(x, sp)
        else:
            z = _fallback_smooth(x, sp)
        candidates.append(z)
        if len(trend_scales) < 3:
            trend_scales.append(z)

    if _HAVE_SCIPY and n >= 16:
        for cutoff in (0.055, 0.085, 0.13, 0.20):
            try:
                candidates.append(sosfiltfilt(butter(3, cutoff, output="sos"), x))
            except Exception:
                pass

    candidates.extend(_spline_candidates(x))
    candidates.extend(_ssa_candidates(x, window_size))

    persistent = _persistent_extrema_candidate(
        trend_scales, n, max(2, int(window_size) // 4)
    )
    if persistent is not None:
        candidates.append(persistent)

    valid = []
    for z in candidates:
        z = np.asarray(z, dtype=float)
        if z.shape != x.shape or not np.all(np.isfinite(z)):
            continue
        corr = _safe_corr(z, x)
        if corr >= 0.20 or np.std(z) < 1e-12:
            valid.append((_quality(x, z), z))

    best = min(valid, key=lambda item: item[0])[1] if valid else x
    return np.asarray(best[window_size - 1:], dtype=float).copy()


def process_signal(input_signal, window_size=20, algorithm_type="enhanced"):
    if algorithm_type == "enhanced":
        return enhanced_filter_with_trend_preservation(input_signal, window_size)
    return adaptive_filter(input_signal, window_size)


def generate_test_signal(length=1000, noise_level=0.3, seed=42):
    rng = np.random.RandomState(seed)
    t = np.linspace(0, 10, length)
    clean_signal = (
        2 * np.sin(2 * np.pi * 0.5 * t)
        + 1.5 * np.sin(2 * np.pi * 2 * t)
        + 0.5 * np.sin(2 * np.pi * 5 * t)
        + 0.8 * np.exp(-t / 5) * np.sin(2 * np.pi * 1.5 * t)
    )
    clean_signal += 0.1 * t * np.sin(0.2 * t)
    clean_signal += np.cumsum(rng.randn(length) * 0.05)
    noisy_signal = clean_signal + rng.normal(0, noise_level, length)
    return noisy_signal, clean_signal


def run_signal_processing(noisy_signal=None, signal_length=1000,
                          noise_level=0.3, window_size=20):
    if noisy_signal is None:
        noisy_signal, clean_signal = generate_test_signal(
            signal_length, noise_level
        )
    else:
        noisy_signal = _finite_signal(noisy_signal)
        clean_signal = None

    filtered_signal = process_signal(noisy_signal, window_size, "enhanced")

    if clean_signal is None:
        return {
            "filtered_signal": filtered_signal,
            "clean_signal": None,
            "noisy_signal": None,
            "correlation": 0,
            "noise_reduction": 0,
            "signal_length": len(filtered_signal),
        }

    delay = window_size - 1
    aligned_clean = clean_signal[delay:]
    aligned_noisy = noisy_signal[delay:]
    m = min(len(filtered_signal), len(aligned_clean))
    filtered_signal = filtered_signal[:m]
    aligned_clean = aligned_clean[:m]
    aligned_noisy = aligned_noisy[:m]

    correlation = _safe_corr(filtered_signal, aligned_clean) if m > 1 else 0.0
    before = np.var(aligned_noisy - aligned_clean)
    after = np.var(filtered_signal - aligned_clean)
    reduction = (before - after) / before if before > 0 else 0.0

    return {
        "filtered_signal": filtered_signal,
        "clean_signal": aligned_clean,
        "noisy_signal": aligned_noisy,
        "correlation": correlation,
        "noise_reduction": reduction,
        "signal_length": m,
    }


if __name__ == "__main__":
    results = run_signal_processing()
    print("Signal processing completed!")
    print(f"Correlation with clean signal: {results['correlation']:.3f}")
    print(f"Noise reduction: {results['noise_reduction']:.3f}")
    print(f"Processed signal length: {results['signal_length']}")

